import Foundation
import CoreLocation

// MARK: - Saved location

/// A user-added place whose weather comes from WeatherKit.
struct SavedLocation: Codable, Identifiable, Hashable {
    let id: UUID
    let name: String
    let latitude: Double
    let longitude: Double
    /// The place's time zone, captured from MapKit when it was added. WeatherKit doesn't return one.
    let timeZoneIdentifier: String?

    /// Creates a saved location.
    /// - Parameters:
    ///   - id: Stable identifier; a new one is generated by default.
    ///   - name: Display name, e.g. "Denton, TX".
    ///   - latitude: Latitude in degrees.
    ///   - longitude: Longitude in degrees.
    ///   - timeZoneIdentifier: The place's time zone, if known.
    init(id: UUID = UUID(), name: String, latitude: Double, longitude: Double, timeZoneIdentifier: String?) {
        self.id = id
        self.name = name
        self.latitude = latitude
        self.longitude = longitude
        self.timeZoneIdentifier = timeZoneIdentifier
    }

    var location: CLLocation {
        CLLocation(latitude: latitude, longitude: longitude)
    }

    /// The stored time zone, falling back to the device's.
    var timeZone: TimeZone {
        timeZoneIdentifier.flatMap(TimeZone.init(identifier:)) ?? .current
    }
}

// MARK: - Selection

/// Which location the dashboard is showing.
/// `.station` uses the Tempest APIs; everything else uses WeatherKit.
enum LocationSelection: Codable, Hashable {
    case station
    case currentLocation
    case saved(UUID)
}
